// ─── File: ClientCredentialsDemo.java ───
package com.bank.clientcred;

import java.util.*;
import java.util.logging.*;

public class ClientCredentialsDemo {
    private static final Logger log = Logger.getLogger(ClientCredentialsDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuthorizationServer authServer = new AuthorizationServer();
        FraudCheckServer fraudCheck = new FraudCheckServer();

        // Settlement service authenticates as ITSELF (no user) and requests fraud:check.
        String token = authServer.tokenForClient("settlement-service", "correct-secret", Set.of("fraud:check"));
        log.info(() -> "Settlement service obtained M2M token with scopes: fraud:check");

        // Call the protected fraud-check API with the service token.
        String verdict = fraudCheck.check(token, "TXN-9001", 95000);
        log.info(() -> "Fraud-check responded: " + verdict);

        // Request a scope the client is NOT allowed -> refused at token issue.
        try {
            authServer.tokenForClient("settlement-service", "correct-secret", Set.of("account:close"));
        } catch (ClientAuthException e) {
            log.severe("Scope refused at token endpoint: " + e.getMessage());
        }

        // Wrong secret -> no token.
        try {
            authServer.tokenForClient("settlement-service", "wrong-secret", Set.of("fraud:check"));
        } catch (ClientAuthException e) {
            log.severe("Client auth failed: " + e.getMessage());
        }
    }
}

