class ClientAuthException extends RuntimeException {
    ClientAuthException(String m) { super(m); }
}

// ─── Would be in InsufficientScopeException.java ───
class InsufficientScopeException extends RuntimeException {
    InsufficientScopeException(String m) { super(m); }
}

// ─── Would be in AuthorizationServer.java ───
class AuthorizationServer {
    // client_id -> {secret, allowedScopesCsv}
    private final Map<String, String[]> clients = Map.of(
        "settlement-service", new String[]{"correct-secret", "fraud:check"},
        "reporting-service",  new String[]{"correct-secret", "account:read"});

    String tokenForClient(String clientId, String secret, Set<String> requestedScopes) {
        String[] rec = clients.get(clientId);
        if (rec == null || !rec[0].equals(secret))
            throw new ClientAuthException("invalid client credentials for " + clientId);
        Set<String> allowed = new HashSet<>(Arrays.asList(rec[1].split(",")));
        if (!allowed.containsAll(requestedScopes))
            throw new ClientAuthException("client not allowed scopes: " + requestedScopes);
        return "m2m-token:" + clientId + ":" + String.join(",", requestedScopes);
    }
}

// ─── Would be in FraudCheckServer.java ───
class FraudCheckServer {
    String check(String token, String txnId, long amount) {
        if (!token.contains(":fraud:check"))
            throw new InsufficientScopeException("token lacks fraud:check scope");
        return amount > 90000 ? "REVIEW" : "CLEAR";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
